        redacted: false,
        durableRef,
        bundle: durableRef ? parseBundleRef(durableRef).bundle : null,
        asset: shown,
        feedback: feedbackFor(durableRef),
        feedbackRequireReason: loadConfig().feedback?.requireReason !== false,
        links,
        headings: headings.map((heading, i) => ({ ...heading, slug: slugs[i] })),
